package studio.solocamera;
public final class PresenterGeometryTest {
 public static void main(String[] args){for(int[] screen:new int[][]{{1080,2400},{2400,1080},{720,1600},{320,480}}){for(float x:new float[]{-1,0,.4f,1,2,Float.NaN})for(float y:new float[]{-1,0,.8f,1,2,Float.NaN}){int[] circle=PresenterGeometry.bounds(screen[0],screen[1],80,100,400,x,y,false);if(circle[2]!=circle[3]||circle[0]<0||circle[1]<80||circle[0]+circle[2]>screen[0]||circle[1]+circle[3]>screen[1]-100)throw new AssertionError("Offscreen circle");int[] full=PresenterGeometry.bounds(screen[0],screen[1],80,100,400,x,y,true);if(full[0]!=0||full[1]!=80||full[2]!=screen[0]||full[3]!=screen[1]-180)throw new AssertionError("Not fullscreen");int[] restored=PresenterGeometry.bounds(screen[0],screen[1],80,100,400,x,y,false);if(!java.util.Arrays.equals(circle,restored))throw new AssertionError("Position lost");}}System.out.println("PASS 144 presenter positions: circle containment, fullscreen coverage, resize/rotation bounds and restored position");}
}
